+                {
+                    return Path.GetFullPath(dir);
+                }
+            }
+            catch
+            {
+                // ignore
+            }
+        }
+
+        return null;
+    }
+
+    private static string? GetGuidePath(string? docsDir) =>
+        string.IsNullOrWhiteSpace(docsDir)
+            ? null
+            : Path.Combine(docsDir, "ORION_SOURCE_GUIDE.md");
