+        {
+            SetState(PlaybackState.Ended);
+            EndReached?.Invoke(this, EventArgs.Empty);
+        });
+        _player.TimeChanged += (_, e) => Post(() =>
+        {
+            if (e.Time > 0 && State is PlaybackState.Opening or PlaybackState.Buffering)
+            {
