+            return absolute.ToString();
+        }
+
+        if (baseUri is not null && Uri.TryCreate(baseUri, value, out var resolved)
+            && (resolved.Scheme == Uri.UriSchemeHttp || resolved.Scheme == Uri.UriSchemeHttps))
