+        var merged = VideoSourceMerger.Merge(subscription, extra);
+        Assert.Equal(3, merged.Count);
+        var demo = Assert.Single(merged, s => s.Key == "demo");
+        Assert.Equal("New", demo.Name);
+        Assert.Equal("https://new.example/vod", demo.Api);
