+        Assert.Equal(expected, HomeCategoryMatcher.IsBroadTag(tag));
+    }
+
+    [Fact]
+    public void FindHomeCategory_movie_hot_matches_movie_category()
+    {
+        // 热门 + movie 走特例：候选为 ["电影","电影片"]
